def find_orfs(s, minlen=90):
    orfs = []
    for frame in range(3):
        i = frame
        stop_positions = []
        # collect stops in this frame
        while i + 3 <= len(s):
            if s[i:i+3] in stops3:
                stop_positions.append(i)
            i += 3
        # walk through, find ATG..stop segments
        last_stop = frame  # treat region before any stop as open from frame start
        # build by scanning codon by codon, tracking current ORF
        start = None
        j = frame
        while j + 3 <= len(s):
            codon = s[j:j+3]
            if start is None and codon == 'ATG':
                start = j
            if codon in stops3:
