import re
from collections import Counter

lines = open('region.fasta').read().split('\n',1)[1]
seq = ''.join(l for l in lines.split('\n') if l).upper()
N = len(seq)
rc = seq[::-1].translate(str.maketrans('ACGT','TGCA'))

stops3 = {'TAA','TAG','TGA'}

def scan(s, minlen=240):   # >=80 codons
    out = []
    for frame in range(3):
        start = None
        for i in range(frame, len(s)-2, 3):
            cod = s[i:i+3]
            if start is None:
                if cod == 'ATG': start = i
            elif cod in stops3:
                L = i+3-start
                if L >= minlen:
                    prot = s[start:i]
                    out.append((start, i+3, L, prot.count('*')==0))
                start = None
        if start is not None and len(s)-start >= minlen:
            prot = s[start:]
            out.append((start, len(s), len(s)-start, prot.count('*')==0))
    return out

print("Forward-strand ORFs (>=80 aa, clean):")
for st, en, L, clean in scan(seq):
    print(f"  region nt {st+1}..{en}  ({L} nt, {(L-3)//3} aa)  internal stops: {not clean}")

print("\nReverse-strand ORFs (>=80 aa, clean), reported in REGION coordinates:")
for st, en, L, clean in scan(rc):
    # rc index i (0-based) corresponds to region nt (1-based) = N - i
    r_start = N - (en-1)     # rc position en-1 is last nt; region coord
    r_end   = N - st
    print(f"  region nt {r_start}..{r_end} (minus strand)  ({L} nt, {(L-3)//3} aa)  internal stops: {not clean}")

# largest reverse-strand ORF regardless of minimum, for comparison
print("\nLongest reverse-strand ORF (no min length):")
allr = scan(rc, minlen=0)
if allr:
    st, en, L, clean = max(allr, key=lambda o: o[2])
    print(f"  region nt {N-(en-1)}..{N-st} ({L} nt, {(L-3)//3} aa)")

# ---- repeat scan on whole region: exact k-mer repeats (k=12+, Allow overlaps)
print("\nLongest exact repeat (tandem or dispersed), k>=12:")
found = []
for k in range(15, 11, -1):
    seen = {}
    rep = []
    for i in range(N-k+1):
        km = seq[i:i+k]
        if km in seen:
            rep.append((seen[km]+1, i+1, km))
        else:
            seen[km] = i
    if rep:
        found = (k, rep[:10])
        break
if found:
    k, reps = found
    print(f"  (k={k}) first occurrences:")
    for a, b, km in reps:
        print(f"   nt {a} and nt {b} share {k}-mer ...")
else:
    print("  none >=12")

# ---- simple low-complexity / homopolymer scan
print("\nHomopolymers >= 8 nt:")
for m in re.finditer(r'([ACGT])\1{7,}', seq):
    print(f"  nt {m.start()+1}-{m.end()}: {m.group()[0]}x{len(m.group())}")

print("\nAT- or GC-rich simple repeats (>=16 nt period-1/2):")
for m in re.finditer(r'(?:AT|TA|GC|CG|GT|TG|CA|AC){8,}', seq):
    print(f"  nt {m.start()+1}-{m.end()}: {m.group()[:40]}...")
